  void ApplyState(State data){state.ModelOptions=data.ModelOptions??new ModelOptions();state.ModelPath=data.ModelPath;state.StepIntervalMs=data.StepIntervalMs;Actions.StepIntervalMs=state.StepIntervalMs??15;LocalLlm.Shared.Stop();state.Gestures=data.Gestures;state.AllowRemappedInput=engine.AllowRemappedInput=data.AllowRemappedInput;gestures.CancelCapture();state.Dark=data.Dark;state.ThemeId=data.ThemeId;state.CustomThemes=data.CustomThemes;ThemeCatalog.Normalize(state);state.UseGpu=data.UseGpu;state.GuideEnabled=data.GuideEnabled;state.GuideHoldKey=data.GuideHoldKey;state.ActiveProfileId=data.ActiveProfileId;Theme.Apply(state.ThemeId,state.Dark,state.CustomThemes);state.Bindings=data.Bindings;state.Profiles=data.Profiles;state.Preferences=data.Preferences;state.ApplicationPaths=data.ApplicationPaths;updatingProfile=true;try{activeProfile.ItemsSource=state.Profiles;activeProfile.SelectedValue=state.ActiveProfileId;}finally{updatingProfile=false;}}
