 public sealed class ImportWindow:Window {
  readonly State current,incoming;readonly Dictionary<string,TextBox> mappings=new Dictionary<string,TextBox>(StringComparer.OrdinalIgnoreCase);readonly CheckBox enable=new CheckBox{Content="Enable when importing enabled and conflicting assignments",IsChecked=false};readonly TextBlock feedback=Theme.Text("",12,"Muted");public ImportResult Result;
  public ImportWindow(State existing,State source){current=existing;incoming=source;Style=(Style)Application.Current.FindResource(typeof(Window));Title="Import Macro+ • Settings";Width=820;Height=740;MinWidth=650;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;Brand.Fit(this);var dock=new DockPanel{Margin=new Thickness(24)};Content=dock;var footer=new StackPanel();footer.Children.Add(enable);footer.Children.Add(feedback);var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};actions.Children.Add(Theme.Button("Cancel",()=>DialogResult=false));actions.Children.Add(Theme.Button("Add assignments",Commit,true));footer.Children.Add(actions);DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);var form=new StackPanel();dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});form.Children.Add(Theme.Text(incoming.Bindings.Count+" shortcuts • "+incoming.Profiles.Count+" profiles",23));form.Children.Add(Theme.Text("Existing assignments are preserved. Match missing application paths with .exe files on this computer. Invalid or conflicting assignments are disabled; you can edit them later.",13,"Muted"));
   foreach(string path in Transfer.Paths(incoming)){string oldPath=path;var title=Theme.Text(path,12,"Muted");title.Margin=new Thickness(0,15,0,5);form.Children.Add(title);var row=new DockPanel();var box=new TextBox{Text=File.Exists(path)?path:existing.ApplicationPaths.Where(p=>File.Exists(p)&&Rules.SameApp(Path.GetFileName(p),Path.GetFileName(path))).UniquePath()??path};mappings[path]=box;var select=Theme.Button("Choose .exe",()=>{var dialog=new OpenFileDialog{Filter="Application|*.exe"};if(dialog.ShowDialog(this)==true)mappings[oldPath].Text=dialog.FileName;});DockPanel.SetDock(select,Dock.Right);row.Children.Add(select);row.Children.Add(box);form.Children.Add(row);}
  }
  void Commit(){try{Result=Transfer.Import(current,incoming,mappings.ToDictionary(p=>p.Key,p=>p.Value.Text.Trim(),StringComparer.OrdinalIgnoreCase),enable.IsChecked==true);DialogResult=true;}catch(Exception error){feedback.Text=error.Message;}}
 }
 static class EnumerableTools {public static string UniquePath(this IEnumerable<string> source){var values=source.Take(2).ToArray();return values.Length==1?values[0]:null;}}
